from itertools import combinations

def is_golomb_ruler(marks):
    """Check if a set of marks forms a Golomb ruler (all pairwise distances unique)."""
    distances = []
    for i, j in combinations(marks, 2):
        d = abs(i - j)
        if d in distances:
            return False
        distances.append(d)
    return True

def find_golomb_ruler_with_constraint(n_marks=7, fixed={0: 0, 1: 2}):
    """
    Find a Golomb ruler with n_marks marks using backtracking.
    fixed: dict of {index: value} for fixed positions
    """
    # Known optimal/near-optimal Golomb rulers for 7 marks
    # Optimal 7-mark Golomb ruler has length 25
    # Let's use constraint programming approach

    from itertools import combinations

    def backtrack(marks, idx):
        if idx == n_marks:
            return marks if is_golomb_ruler(marks) else None

        # Determine starting value
        start = marks[-1] + 1 if marks else 0

        # If this index has a fixed value
        if idx in fixed:
            val = fixed[idx]
            if val < start:
                return None
            new_marks = marks + [val]
            # Check partial Golomb property
            existing_dists = set()
            valid = True
            for i in range(len(new_marks)):
                for j in range(i+1, len(new_marks)):
                    d = new_marks[j] - new_marks[i]
                    if d in existing_dists:
                        valid = False
                        break
                    existing_dists.add(d)
                if not valid:
                    break
            if valid:
                return backtrack(new_marks, idx + 1)
            return None

        # Try values from start upward (with a reasonable upper bound)
        # Best known 7-mark Golomb ruler has length 25
        upper_bound = 200  # generous upper bound

        for val in range(start, upper_bound):
            new_marks = marks + [val]
            # Check partial Golomb property
            existing_dists = set()
            valid = True
            for i in range(len(new_marks)):
                for j in range(i+1, len(new_marks)):
                    d = new_marks[j] - new_marks[i]
                    if d in existing_dists:
                        valid = False
                        break
                    existing_dists.add(d)
                if not valid:
                    break
            if valid:
                result = backtrack(new_marks, idx + 1)
                if result is not None:
                    return result

        return None

    # Start with fixed[0] = 0
    return backtrack([], 0)

result = find_golomb_ruler_with_constraint()
print("Found Golomb ruler:", result)
if result:
    print("Verification - all pairwise distances:")
    dists = []
    for i, j in combinations(result, 2):
        dists.append(abs(i-j))
    print(sorted(dists))
    print("All unique?", len(dists) == len(set(dists)))
    print("x[0]=0?", result[0] == 0)
    print("x[1]=2?", result[1] == 2)
